package com.google.gson.stream;

import java.io.*;
import java.io.Closeable;
import java.io.Flushable;
import java.io.IOException;
import java.io.Writer;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

public class JsonWriter_nullValue_TriageGen2Test {

    private JsonWriter jsonWriter;
    private Writer mockWriter;

    @Before
    public void setUp() throws IOException {
        mockWriter = mock(Writer.class);
        jsonWriter = new JsonWriter(mockWriter);
    }

    @Test
    public void testNullValueWithSerializeNullsTrue() throws IOException {
        jsonWriter.setSerializeNulls(true);
        jsonWriter.name("testName");
        jsonWriter.nullValue();
        verify(mockWriter).write("null");
    }

    @Test
    public void testNullValueWithSerializeNullsFalse() throws IOException {
        jsonWriter.setSerializeNulls(false);
        jsonWriter.name("testName");
        jsonWriter.nullValue();
        verify(mockWriter, times(0)).write("null");
        assertNull(jsonWriter.deferredName);
    }

    @Test
    public void testNullValueWithoutName() throws IOException {
        jsonWriter.setSerializeNulls(true);
        jsonWriter.nullValue();
        verify(mockWriter).write("null");
    }

    @Test
    public void testNullValueWithSerializeNullsTrueAndNoName() throws IOException {
        jsonWriter.setSerializeNulls(true);
        jsonWriter.nullValue();
        verify(mockWriter).write("null");
    }

    @Test
    public void testNullValueWithSerializeNullsFalseAndNoName() throws IOException {
        jsonWriter.setSerializeNulls(false);
        jsonWriter.nullValue();
        verify(mockWriter, times(0)).write("null");
    }

    @Test(expected = IOException.class)
    public void testNullValueThrowsIOException() throws IOException {
        when(mockWriter.write("null")).thenThrow(new IOException());
        jsonWriter.setSerializeNulls(true);
        jsonWriter.name("testName");
        jsonWriter.nullValue();
    }

    @Test
    public void testNullValueWithNullDeferredName() throws IOException {
        jsonWriter.setSerializeNulls(true);
        when(jsonWriter.deferredName).thenReturn(null);
        jsonWriter.nullValue();
        verify(mockWriter).write("null");
    }
}
